// HasScheduleItems applies the HasEdge predicate on the "schedule_items" edge.
func HasScheduleItems() predicate.BillingTerm {
	return predicate.BillingTerm(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, ScheduleItemsTable, ScheduleItemsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasScheduleItemsWith applies the HasEdge predicate on the "schedule_items" edge with a given conditions (other predicates).
func HasScheduleItemsWith(preds ...predicate.BillingScheduleItem) predicate.BillingTerm {
	return predicate.BillingTerm(func(s *sql.Selector) {
		step := newScheduleItemsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BillingTerm) predicate.BillingTerm {
	return predicate.BillingTerm(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BillingTerm) predicate.BillingTerm {
	return predicate.BillingTerm(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BillingTerm) predicate.BillingTerm {
	return predicate.BillingTerm(sql.NotPredicates(p))
}
